BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷256", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。引文按原文保留，疑似转录讹字单独注明。", "url": "https://github.com/greed-216/histree/blob/fdc81a0b21a4c29dcfb4a4ecc9006df86ffe9248/resources/derived/tongjian/256.txt", "note": "卷256中和四年21段；原始电子文本与SHA-256见来源清单。", "id": "a38849fc-5d04-59ee-ae04-1830b68b7d1a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王行瑜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：王行瑜。", "biography": null, "status": "draft", "id": "65e50f4b-8971-5070-b043-77c6748c1fc0"}, {"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "杨守宗", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：杨守宗。", "biography": null, "status": "draft", "id": "b0ea039c-38ae-5baf-9c5c-3240ffeaedef"}, {"name": "顾彦朗", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：顾彦朗。", "biography": null, "status": "draft", "id": "f94b234c-1029-562a-8d41-de3e70fa7892"}, {"name": "杨守亮", "aliases": ["訾亮"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨守亮。", "biography": null, "status": "draft", "id": "794556be-c340-512f-923f-61f100db55df"}, {"name": "董昌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：董昌。", "biography": null, "status": "draft", "id": "873d5b10-b461-5308-baa9-da26022436b4"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "秦宗权", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的秦宗权，在此段中为遣兵者。", "biography": null, "status": "draft", "id": "4ab9b100-f137-522e-9b11-1ef372de9edf"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱珍", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的朱珍，在此段中为击退者。", "biography": null, "status": "draft", "id": "863c86d4-bcc1-57f7-a877-4c9d05eed8ca"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "李国昌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：李国昌。", "biography": null, "status": "draft", "id": "3a4d0136-a49a-5c49-b83b-5ad2835d7462"}, {"name": "萧遘", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：萧遘。", "biography": null, "status": "draft", "id": "4eb0a98d-80ed-52f0-9e2c-2a84e77f2147"}, {"name": "郑昌图", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑昌图。", "biography": null, "status": "draft", "id": "e873d448-fba7-591c-8f89-710c5ad67716"}, {"name": "裴澈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：裴澈。", "biography": null, "status": "draft", "id": "218df366-f371-537f-8710-a07a8460f214"}, {"name": "杜让能", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杜让能。", "biography": null, "status": "draft", "id": "e3eae55f-2032-5c76-905f-e480ad32ea69"}, {"name": "李昌符", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：李昌符。", "biography": null, "status": "draft", "id": "40f447e6-4770-5e94-9e87-b48375844b3d"}, {"name": "郑从谠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑从谠。", "biography": null, "status": "draft", "id": "15f99f06-f58e-5b7f-8845-549c1edaad2d"}, {"name": "周宝", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：周宝。", "biography": null, "status": "draft", "id": "1e6765bf-c951-5059-bfff-7713a7591fc6"}, {"name": "薛朗", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：薛朗。", "biography": null, "status": "draft", "id": "40150662-123e-5c52-a83c-fe5051e0f432"}, {"name": "刘浩", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：刘浩。", "biography": null, "status": "draft", "id": "ba30c112-8032-5113-b1f6-da3664628ebb"}, {"name": "丁从实", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：丁从实。", "biography": null, "status": "draft", "id": "69ac26ef-1e24-5434-8dcc-98f6380d7187"}, {"name": "高骈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的高骈，在此段中为受呈者。", "biography": null, "status": "draft", "id": "c4d5b35a-b520-57df-87da-baff9480b7e4"}, {"name": "吕用之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的吕用之，在此段中为被指控者。", "biography": null, "status": "draft", "id": "cd08ae2a-9825-5636-a942-312bb29aed61"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "周庠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：周庠。", "biography": null, "status": "draft", "id": "fb440e5b-1571-58ce-8ca0-85a0e1b24122"}, {"name": "杨茂实", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：杨茂实。", "biography": null, "status": "draft", "id": "96422f5a-d81e-5b37-9ebe-c5d3bc492c95"}, {"name": "张虔裕", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：张虔裕。", "biography": null, "status": "draft", "id": "f581f1ed-0ca1-5e65-b451-15f979ee4193"}, {"name": "綦毋谏", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：綦毋谏。", "biography": null, "status": "draft", "id": "4769c0e1-c6f1-5164-bf85-96e3579bdc54"}, {"name": "徐约", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：徐约。", "biography": null, "status": "draft", "id": "478eb858-866b-5fb9-903c-5858171f2d8f"}]'::jsonb)
