INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "王行瑜等五将获任节度使", "start_year": 887, "end_year": 887, "time_original": "光启三年春正月", "dynasty": "唐", "description": "朝廷任王行瑜为静难军节度使、李茂贞领武定节度使、杨守宗为金商节度使、顾彦朗为东川节度使、杨守亮为山南西道节度使。", "phases": [], "location_name": "静难、武定、金商、东川、山南西道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2d9487ea-8405-5a9d-8d66-4657cca4c926"}, {"title": "董昌、钱镠获正式任命", "start_year": 887, "end_year": 887, "time_original": "光启三年正月辛巳", "dynasty": "唐", "description": "朝廷任董昌为浙东观察使，钱镠为杭州刺史。", "phases": [], "location_name": "浙东、杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2d6bfaaf-6e0c-5f5e-888b-ab023409403b"}, {"title": "朱全忠遣朱珍募兵", "start_year": 887, "end_year": 887, "time_original": "光启三年二月", "dynasty": "唐", "description": "秦宗权计划集中力量攻汴州；朱全忠因兵力不足，任朱珍为淄州刺史，遣其到东道募兵，约定初夏返回。", "phases": [], "location_name": "淄州、东道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d55460d9-4401-5841-a3ad-80232993b677"}, {"title": "田令孜被削官长流端州，实际未行", "start_year": 887, "end_year": 887, "time_original": "光启三年二月戊辰", "dynasty": "唐", "description": "朝廷削田令孜官爵，下令长流端州；田令孜依附陈敬瑄，流放令最终未执行。", "phases": [], "location_name": "端州、西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a693959e-b246-5816-8da3-83a9f8d29e0d"}, {"title": "代北节度使李国昌去世", "start_year": 887, "end_year": 887, "time_original": "光启三年二月后条；具体日未载", "dynasty": "唐", "description": "代北节度使李国昌去世。", "phases": [], "location_name": "代北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dae9d6e6-5b83-52e2-b059-ca9f61fb6b86"}, {"title": "萧遘、郑昌图、裴澈在岐山被斩", "start_year": 887, "end_year": 887, "time_original": "光启三年三月癸未", "dynasty": "唐", "description": "朝廷下诏将曾受襄王煴方面官职的萧遘、郑昌图、裴澈示众处斩，三人均死于岐山。", "phases": [], "location_name": "岐山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "acbe742d-f51f-537a-bdcd-f98e3dd35040"}, {"title": "杜让能力争，部分受襄王官职朝士免死", "start_year": 887, "end_year": 887, "time_original": "光启三年三月癸未后", "dynasty": "唐", "description": "法司拟严惩众多曾受襄王煴官职的朝士，杜让能力争，史书记载多数获免。", "phases": [], "location_name": "行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1d17e1e0-88ff-5139-9372-d7321ef97e44"}, {"title": "僖宗车驾至凤翔，李昌符请求暂驻", "start_year": 887, "end_year": 887, "time_original": "光启三年三月壬辰", "dynasty": "唐", "description": "皇帝车驾抵凤翔；李昌符以宫室未完为由，请皇帝驻于其府舍，获准。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a0279b08-c1f7-5d58-a67c-bfc5bb141e48"}, {"title": "郑从谠罢太傅兼侍中，任太子太保", "start_year": 887, "end_year": 887, "time_original": "光启三年三月条；具体日未载", "dynasty": "唐", "description": "郑从谠由太傅兼侍中改任太子太保。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "57b179db-0d48-5c41-b6ba-ed0bdc86db67"}, {"title": "周宝先前募后楼兵，镇海军生怨", "start_year": null, "end_year": null, "time_original": "镇海军变前；确年待考", "dynasty": "唐", "description": "周宝募待遇较高的亲军后楼兵，普通镇海军不满；其后楼兵渐骄横，筑城劳役亦使民众困苦。", "phases": [], "location_name": "镇海", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8a4c6730-8ca6-5250-bb71-eafb11a50216"}, {"title": "刘浩率镇海军兵变，周宝逃常州", "start_year": 887, "end_year": 887, "time_original": "光启三年三月癸巳前夜及当日", "dynasty": "唐", "description": "薛朗将周宝威胁镇海军的话转告刘浩，刘浩当夜率党攻府舍；周宝逃常州依丁从实，刘浩杀多名僚佐。", "phases": [], "location_name": "镇海、常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "549d3637-8cbe-533b-85ae-1d6a99cf1779"}, {"title": "刘浩军推薛朗为镇海留后", "start_year": 887, "end_year": 887, "time_original": "光启三年三月癸巳", "dynasty": "唐", "description": "刘浩军迎薛朗入府，推其为留后。", "phases": [], "location_name": "镇海", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3e335ee9-00d5-56ff-9397-6484aa84f69a"}, {"title": "高骈闻周宝败，送齑粉相讥", "start_year": 887, "end_year": 887, "time_original": "镇海兵变后；具体日未载", "dynasty": "唐", "description": "高骈听闻周宝败走后接受祝贺，并遣人送齑粉；周宝愤怒，回称高骈有吕用之，后事未定。", "phases": [], "location_name": "扬州、常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "08a3e087-dbd2-53f5-95b5-a72b28778268"}, {"title": "扬州连年饥荒，城中多人饿死", "start_year": null, "end_year": null, "time_original": "连岁；具体年界待考", "dynasty": "唐", "description": "《通鉴》记扬州连年饥荒，城中饿死者众，坊巷萧条。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8b09836e-600f-5727-a06d-845621e3d261"}, {"title": "杨守亮屡召王建，王建不往", "start_year": 887, "end_year": 887, "time_original": "光启三年三月后条；具体日未载", "dynasty": "唐", "description": "杨守亮忌王建勇武，屡次召其前往；王建畏惧而不赴。", "phases": [], "location_name": "利州、山南西道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1fac4c9f-0984-55c3-ba65-a131ed66488a"}, {"title": "王建袭阆州、逐杨茂实", "start_year": 887, "end_year": 887, "time_original": "光启三年三月后条；具体日未载", "dynasty": "唐", "description": "周庠建议王建以杨茂实不修职贡为由进兵；王建招兵沿嘉陵江袭阆州，逐杨茂实，占据该州并自称防御使。", "phases": [], "location_name": "阆州、嘉陵江", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "07c2a8de-7bf7-5411-a29d-9f5b3ccb5e5f"}, {"title": "张虔裕、綦毋谏劝王建奉表及养士爱民", "start_year": 887, "end_year": 887, "time_original": "王建据阆州之后；具体日未载", "dynasty": "唐", "description": "张虔裕建议王建奉表朝廷，綦毋谏建议养士爱民、观望形势；王建均采纳。", "phases": [], "location_name": "阆州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c16d13f4-9da2-5fbd-a64a-593304dfe850"}, {"title": "王建与顾彦朗先前同在神策军", "start_year": null, "end_year": null, "time_original": "“初”追叙；确年待考", "dynasty": "唐", "description": "《通鉴》追叙王建与顾彦朗曾同在神策军、共同讨贼。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "cf0e9367-80f6-5641-ad39-ce93734c0efa"}, {"title": "顾彦朗馈王建军粮，王建未犯东川", "start_year": 887, "end_year": 887, "time_original": "王建据阆州后；具体日未载", "dynasty": "唐", "description": "顾彦朗担心王建侵入东川，数次馈送军粮；王建因此未侵犯东川。", "phases": [], "location_name": "东川、阆州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c0aee30b-dc9e-5262-9889-52cad4371fdc"}, {"title": "周宝先前诱徐约进攻苏州", "start_year": null, "end_year": null, "time_original": "“初”追叙；确年待考", "dynasty": "唐", "description": "《通鉴》卷256末段追叙周宝听闻徐约兵精，诱使他进攻苏州；结果续见下卷。", "phases": [], "location_name": "苏州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d4cb3312-a616-52d1-a378-8cad68a2c44a"}]'::jsonb)
